import * as THREE from 'three';
// One sodium fixture: 15-degree warm spot pool + short warm point fill + emissive head; the cold tint stays global.
export function makeSodiumLamp(x, z, height = 7) {
  const g = new THREE.Group(); g.position.set(x, 0, z); g.userData.tag = 'lamp';
  const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, height, 8), new THREE.MeshStandardMaterial({ color: 0x3a3d40, roughness: 0.8 }));
  pole.position.y = height / 2; g.add(pole);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 12, 8), new THREE.MeshStandardMaterial({ color: 0xff8833, emissive: 0xff8833, emissiveIntensity: 4 }));
  head.position.y = height; g.add(head);
  const spot = new THREE.SpotLight(0xff8833, 6, 30, THREE.MathUtils.degToRad(15), 0.6, 1.2); // intensity 3-8, distance 20-40, 15 deg cone
  spot.position.y = height; spot.target.position.set(0, 0, 0); spot.userData.tag = 'lamp'; g.add(spot, spot.target);
  spot.castShadow = true; spot.shadow.mapSize.set(1024, 1024); spot.shadow.radius = 4; spot.shadow.bias = -0.0005;
  const fill = new THREE.PointLight(0xff8833, 4, 24, 1.6); fill.position.y = height - 0.3; fill.userData.tag = 'lamp'; g.add(fill);
  const halo = new THREE.Mesh(new THREE.CircleGeometry(4.5, 32),                       // warm halo on the ground, tight, additive
    new THREE.MeshBasicMaterial({ color: 0xff8833, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false }));
  halo.rotation.x = -Math.PI / 2; halo.position.y = 0.02; halo.renderOrder = 5; halo.userData.tag = 'lamp-pool'; g.add(halo);
  return g;
}
export function coldField(scene) {
  scene.add(new THREE.HemisphereLight(0x2a4a6f, 0x0d1b2e, 0.35));   // explicit cold shadow tint, not the word "cold"
}
